import React, { useState, useEffect } from 'react';

const TodoList = () => {
  const [taskList, setTaskList] = useState([]);

  useEffect(() => {
    const savedTasks = JSON.parse(localStorage.getItem('todoTasks')) || [];
    setTaskList(savedTasks);
  }, []);

  useEffect(() => {
    localStorage.setItem('todoTasks', JSON.stringify(taskList));
  }, [taskList]);

  const addTask = (itemName, qty) => {
    if (!itemName.trim() || qty <= 0) return;
    const newTask = {
      id: Date.now(),
      itemName,
      qty: Number(qty),
      isDone: false,
    };
    setTaskList(prev => [...prev, newTask]);
  };

  const deleteTask = (id) => {
    const updatedTasks = taskList.filter((item) => item.id !== id);
    setTaskList(updatedTasks);
  };

  const toggleTask = (id) => {
    const updated = taskList.map(task =>
      task.id === id ? { ...task, isDone: !task.isDone } : task
    );
    setTaskList(updated);
  };

  return (
    <div>
      <Form
        addTask={addTask}
        taskList={taskList}
        deleteTask={deleteTask}
        toggleTask={toggleTask}
      />
    </div>
  );
};

export default TodoList;

function Form({ addTask, taskList, deleteTask, toggleTask }) {
  const [itemName, setItemName] = useState('');
  const [qty, setQty] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    addTask(itemName, qty);
    setItemName('');
    setQty('');
  };

  const stats = calculate(taskList);

  return (
    <div>
      <form className='container mt-5 p-3 border border-2 rounded bg-info-subtle' onSubmit={handleSubmit}>
        <section className="mb-3 mt-2">
          <h2 className="text-center text-dark">
            <span className='badge bg-dark m-3'>Things To Bring</span>
          </h2>
          <input
            type="text"
            className="form-control"
            placeholder='Enter Item Name'
            value={itemName}
            onChange={(e) => setItemName(e.target.value)}
          />
          <input
            type="number"
            className="form-control mt-2"
            placeholder='Quantity'
            value={qty}
            onChange={(e) => setQty(e.target.value)}
          />
        </section>
        <input type='submit' className="btn btn-sm btn-dark text-white" value="Add Task" />

        <TaskList taskList={taskList} deleteTask={deleteTask} toggleTask={toggleTask} />

        {/* Summary Section */}
        <div className="mt-4">
          <h5 className="text-center text-dark">Summary</h5>
          <ul className="list-group">
            <li className="list-group-item">Total Items: {stats.totalTasks}</li>
            <li className="list-group-item">Total Quantity: {stats.totalQty}</li>
            <li className="list-group-item">Packed Items: {stats.packedCount}</li>
            <li className="list-group-item">Packed Quantity: {stats.packedQty}</li>
          </ul>
        </div>
      </form>
    </div>
  );
}

function TaskList({ taskList, deleteTask, toggleTask }) {
  if (taskList.length === 0) {
    return <h4 className='text-center mt-3 text-danger'>Your cart is empty</h4>;
  }
  return (
    <ul className='list-group mt-3'>
      {taskList.map((item) => (
        <Task key={item.id} item={item} deleteTask={deleteTask} toggleTask={toggleTask} />
      ))}
    </ul>
  );
}

function Task({ item, deleteTask, toggleTask }) {
  const { itemName, qty, id, isDone } = item;

  return (
    <li className='list-group-item d-flex justify-content-between align-items-center'>
      <span className='text-monospace fs-5'>
        <input
          type="checkbox"
          className='me-2'
          checked={isDone}
          onChange={() => toggleTask(id)}
        />
        <span style={{ textDecoration: isDone ? 'line-through' : 'none' }}>
          {itemName}
        </span>
        <span className='badge bg-primary rounded-pill ms-2'>{qty}</span>
      </span>
      <button className='btn btn-danger btn-sm' onClick={() => deleteTask(id)}>
        Delete
      </button>
    </li>
  );
}

function calculate(items) {
  const totalTasks = items.length;
  const totalQty = items.reduce((sum, item) => sum + item.qty, 0);
  const packedCount = items.filter(item => item.isDone).length;
  const packedQty = items.reduce((sum, item) => item.isDone ? sum + item.qty : sum, 0);

  return { totalTasks, totalQty, packedCount, packedQty };
}
